SELECT 
FROM hall h WHERE h.cinema_id = #{cinemaId}
ORDER BY h.name ASC, h.hall_id ASC

SELECT ,
       (SELECT COUNT(1) FROM show_schedule s WHERE s.hall_id = h.hall_id) AS showCount
FROM hall h
WHERE h.cinema_id = #{cinemaId}
ORDER BY h.name ASC, h.hall_id ASC
LIMIT #{limit} OFFSET #{offset}
